coding.solution:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n, x;
    if (!(cin >> n >> x)) return 0;
    vector<int> a(n);
    for (int &v : a) cin >> v;
    int l = 0, r = n - 1, ans = -1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (a[m] < x) l = m + 1;
        else {
            if (a[m] == x) ans = m;
            r = m - 1;
        }
    }
    cout << (ans == -1 ? -1 : ans + 1) << "\n";
    return 0;
}

