#include <iostream>
using namespace std;
int main() {
    int n, s;
    if (!(cin >> n >> s)) return 0;
    long long ans = 0;
    for (int a = 0; a <= n; ++a) {
        if (2 * a > s) break;
        for (int b = 0; b <= n - a; ++b) {
            if (2 * a + 3 * b > s) break;
            int c = n - a - b;
            if (2 * a + 3 * b + 5 * c == s) ++ans;
        }
    }
    cout << ans << "\n";
    return 0;
}

