#include <iostream>
using namespace std;
int main() {
    int n;
    if (!(cin >> n)) return 0;
    if (n <= 1) {
        cout << 1 << "\n";
        return 0;
    }
    long long prev2 = 1, prev1 = 1;
    for (int i = 2; i <= n; ++i) {
        long long current = prev2 + prev1;
        prev2 = prev1;
        prev1 = current;
    }
    cout << prev1 << "\n";
    return 0;
}

