#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n;
    long long budget;
    if (!(cin >> n >> budget)) return 0;
    vector<long long> a(n);
    for (long long &d : a) cin >> d;
    sort(a.begin(), a.end());
    long long used = 0;
    int answer = 0;
    for (long long d : a) {
        if (used + d > budget) break;
        used += d;
        ++answer;
    }
    cout << answer << "\n";
    return 0;
}
